1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14	)
15	
16	// Point 是一条序列上某个时间戳的采样值。
17	type Point struct {
18		Timestamp int64   `json:"timestamp"`
19		Value     float64 `json:"value"`
20	}
21	
22	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
23	type SeriesView struct {
24		Name   string            `json:"name"`
25		Labels map[string]string `json:"labels"`
26		Points []Point           `json:"points"`
27	}
28	
29	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
30	type QuerySeries struct {
31		Name    string            `json:"name"`
32		Labels  map[string]string `json:"labels"`
33		Count   int               `json:"count"`
34		Average float64           `json:"average"`
35	}
36	
37	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
38	type QueryResult struct {
39		Status string        `json:"status"`
40		Op     string        `json:"op"`
41		Series []QuerySeries `json:"series"`
42	}
43	
44	// BatchResult 是一批采样点写入成功后的结果。
45	type BatchResult struct {
46		Status     string       `json:"status"`
47		Added      int          `json:"added"`
48		Duplicates int          `json:"duplicates"`
49		Series     []SeriesView `json:"series"`
50	}
51	
52	// SeriesRef 标识一条序列：指标名加完整标签集合。
53	// 缺少某个标签与该标签值为空字符串属于不同序列。
54	type SeriesRef struct {
55		Name   string            `json:"name"`
56		Labels map[string]string `json:"labels"`
57	}
58	
59	// Conflict 描述同一序列同一时间戳已存在不同的值。
60	type Conflict struct {
61		Series    SeriesRef `json:"series"`
62		Timestamp int64     `json:"timestamp"`
63		Existing  float64   `json:"existing"`
64		Submitted float64   `json:"submitted"`
65	}
66	
67	// LineError 是一行（一批）输入失败后的结构化结果。
68	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
69	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
70	type LineError struct {
71		Status   string    `json:"status"`
72		Line     int       `json:"line,omitempty"`
73		Index    int       `json:"index,omitempty"`
74		Error    string    `json:"error"`
75		Conflict *Conflict `json:"conflict,omitempty"`
76	}
77	
78	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
79	type MetricStore struct {
80		series map[seriesID]*storedSeries
81	}
82	
83	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
84	type seriesID struct {
85		name string
86		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
87		sig string
88	}
89	
90	type storedSeries struct {
91		ref    SeriesRef
92		points map[int64]float64
93	}
94	
95	// NewMetricStore 创建一个空的指标存储。
96	func NewMetricStore() *MetricStore {
97		return &MetricStore{series: make(map[seriesID]*storedSeries)}
98	}
99	
100	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
101	// 调用方对副本的增删改不影响存储中的序列身份。
102	func cloneLabels(labels map[string]string) map[string]string {
103		out := make(map[string]string, len(labels))
104		for k, v := range labels {
105			out[k] = v
106		}
107		return out
108	}
109	
110	func sortedKeys(m map[string]string) []string {
111		keys := make([]string, 0, len(m))
112		for k := range m {
113			keys = append(keys, k)
114		}
115		sort.Strings(keys)
116		return keys
117	}
118	
119	func makeSeriesID(name string, labels map[string]string) seriesID {
120		var b strings.Builder
121		for _, k := range sortedKeys(labels) {
122			v := labels[k]
123			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
124		}
125		return seriesID{name: name, sig: b.String()}
126	}
127	
128	// labelPair 是标签键值对字典序比较的单元。
129	type labelPair struct {
130		Key, Value string
131	}
132	
133	func sortedPairs(labels map[string]string) []labelPair {
134		keys := sortedKeys(labels)
135		pairs := make([]labelPair, len(keys))
136		for i, k := range keys {
137			pairs[i] = labelPair{Key: k, Value: labels[k]}
138		}
139		return pairs
140	}
141	
142	func compareLabelPairs(a, b []labelPair) int {
143		n := len(a)
144		if len(b) < n {
145			n = len(b)
146		}
147		for i := 0; i < n; i++ {
148			if a[i].Key != b[i].Key {
149				return strings.Compare(a[i].Key, b[i].Key)
150			}
151			if a[i].Value != b[i].Value {
152				return strings.Compare(a[i].Value, b[i].Value)
153			}
154		}
155		switch {
156		case len(a) < len(b):
157			return -1
158		case len(a) > len(b):
159			return 1
160		}
161		return 0
162	}
163	
164	var (
165		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
166		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
167	)
168	
169	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
170	// 成功时返回 BatchResult 或 *QueryResult；失败返回 *LineError（Index 始终为零）。
171	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
172		top, ok, lerr := decodeTopValue(line)
173		if lerr != nil {
174			return nil, lerr
175		}
176		switch ok {
177		case '[':
178			var items []json.RawMessage
179			if err := json.Unmarshal(top, &items); err != nil {
180				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
181			}
182			return s.ingestItems(items)
183		case '{':
184			return s.queryFromObject(top)
185		default:
186			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
187		}
188	}
189	
190	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
191	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
192	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
193		top, ok, lerr := decodeTopValue(line)
194		if lerr != nil {
195			return nil, lerr
196		}
197		if ok != '[' {
198			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
199		}
200		var items []json.RawMessage
201		if err := json.Unmarshal(top, &items); err != nil {
202			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
203		}
204		return s.ingestItems(items)
205	}
206	
207	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
208	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
209		top, ok, lerr := decodeTopValue(line)
210		if lerr != nil {
211			return nil, lerr
212		}
213		if ok != '{' {
214			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
215		}
216		return s.queryFromObject(top)
217	}
218	
219	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
220	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
221	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
222		dec := json.NewDecoder(strings.NewReader(line))
223		var top json.RawMessage
224		if err := dec.Decode(&top); err != nil {
225			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
226		}
227		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
228		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
229			if err == nil {
230				err = fmt.Errorf("unexpected content after the JSON value")
231			}
232			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
233		}
234		trimmed := strings.TrimSpace(string(top))
235		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
236			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
237		}
238		return top, trimmed[0], nil
239	}
240	
241	type parsedSample struct {
242		name   string
243		ts     int64
244		value  float64
245		labels map[string]string
246	}
247	
248	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
249	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
250	func parseSample(raw json.RawMessage) (parsedSample, error) {
251		var p parsedSample
252		p.labels = map[string]string{}
253		dec := json.NewDecoder(bytes.NewReader(raw))
254		dec.UseNumber()
255	
256		tok, err := dec.Token()
257		if err != nil {
258			return p, err
259		}
260		if d, ok := tok.(json.Delim); !ok || d != '{' {
261			return p, fmt.Errorf("each sample must be a JSON object")
262		}
263	
264		present := make(map[string]bool)
265		for dec.More() {
266			keyTok, err := dec.Token()
267			if err != nil {
268				return p, err
269			}
270			key := keyTok.(string)
271			switch key {
272			case "name", "timestamp", "value", "labels":
273			default:
274				return p, fmt.Errorf("unknown field %q", key)
275			}
276			if present[key] {
277				return p, fmt.Errorf("duplicate field %q", key)
278			}
279			present[key] = true
280	
281			switch key {
282			case "name":
283				t, err := dec.Token()
284				if err != nil {
285					return p, err
286				}
287				s, ok := t.(string)
288				if !ok {
289					return p, fmt.Errorf(`field "name" must be a string`)
290				}
291				if s == "" {
292					return p, fmt.Errorf(`field "name" must be a non-empty string`)
293				}
294				p.name = s
295			case "timestamp":
296				n, err := nextJSONNumber(dec, "timestamp")
297				if err != nil {
298					return p, err
299				}
300				v, err := parseJSONInt(n)
301				if err != nil {
302					return p, fmt.Errorf(`field "timestamp": %s`, err)
303				}
304				p.ts = v
305			case "value":
306				n, err := nextJSONNumber(dec, "value")
307				if err != nil {
308					return p, err
309				}
310				v, err := parseFiniteFloat(n)
311				if err != nil {
312					return p, fmt.Errorf(`field "value": %s`, err)
313				}
314				p.value = v
315			case "labels":
316				labels, err := parseLabels(dec, `field "labels" must be an object of string keys to string values`)
317				if err != nil {
318					return p, err
319				}
320				p.labels = labels
321			}
322		}
323		if _, err := dec.Token(); err != nil { // 消耗 '}'
324			return p, err
325		}
326		if _, err := dec.Token(); err != io.EOF {
327			if err == nil {
328				return p, fmt.Errorf("unexpected content after the sample object")
329			}
330			return p, err
331		}
332	
333		for _, field := range []string{"name", "timestamp", "value"} {
334			if !present[field] {
335				return p, fmt.Errorf("missing required field %q", field)
336			}
337		}
338		return p, nil
339	}
340	
341	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
342	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
343	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
344	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
345	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
346		t, err := dec.Token()
347		if err != nil {
348			return nil, err
349		}
350		d, ok := t.(json.Delim)
351		if !ok || d != '{' {
352			return nil, fmt.Errorf("%s", notObjectMsg)
353		}
354		labels := map[string]string{}
355		for dec.More() {
356			labelKeyTok, err := dec.Token()
357			if err != nil {
358				return nil, err
359			}
360			labelKey := labelKeyTok.(string)
361			if labelKey == "" {
362				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
363			}
364			valTok, err := dec.Token()
365			if err != nil {
366				return nil, err
367			}
368			labelVal, ok := valTok.(string)
369			if !ok {
370				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
371			}
372			if _, dup := labels[labelKey]; dup {
373				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
374			}
375			labels[labelKey] = labelVal
376		}
377		if _, err := dec.Token(); err != nil { // 消耗 '}'
378			return nil, err
379		}
380		return labels, nil
381	}
382	
383	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
384		t, err := dec.Token()
385		if err != nil {
386			return "", err
387		}
388		n, ok := t.(json.Number)
389		if !ok {
390			return "", fmt.Errorf(`field %q must be a JSON number`, field)
391		}
392		return n, nil
393	}
394	
395	func parseJSONInt(n json.Number) (int64, error) {
396		s := string(n)
397		if !jsonIntegerRE.MatchString(s) {
398			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
399		}
400		v, err := strconv.ParseInt(s, 10, 64)
401		if err != nil {
402			return 0, fmt.Errorf("must be within int64 range")
403		}
404		return v, nil
405	}
406	
407	func parseFiniteFloat(n json.Number) (float64, error) {
408		s := string(n)
409		if !jsonNumberRE.MatchString(s) {
410			return 0, fmt.Errorf("must be a JSON number")
411		}
412		v, err := strconv.ParseFloat(s, 64)
413		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
414			return 0, fmt.Errorf("must be a finite number representable as float64")
415		}
416		return v, nil
417	}
418	
419	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
420	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
421		type pending struct {
422			id  seriesID
423			ref SeriesRef
424			ts  int64
425			val float64
426		}
427	
428		added := 0
429		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
430		seen := make(map[seriesID]map[int64]float64)
431		// 仅记录需要落盘的新增点；校验全部通过后才提交。
432		commits := make([]pending, 0, len(items))
433	
434		failAt := func(index int, msg string) *LineError {
435			return &LineError{Status: "error", Index: index, Error: msg}
436		}
437		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
438			return &LineError{
439				Status: "error",
440				Index:  index,
441				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
442					ref, ts, formatFloat(existing), formatFloat(submitted)),
443				Conflict: &Conflict{
444					// 标签必须复制：冲突结果是本次失败的独立记录，
445					// 调用方修改它不能改动已存序列的身份。
446					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
447					Timestamp: ts,
448					Existing:  existing,
449					Submitted: submitted,
450				},
451			}
452		}
453	
454		for i, item := range items {
455			pos := i + 1
456			p, err := parseSample(item)
457			if err != nil {
458				return nil, failAt(pos, err.Error())
459			}
460	
461			id := makeSeriesID(p.name, p.labels)
462			ref := SeriesRef{Name: p.name, Labels: p.labels}
463	
464			if byTS, ok := seen[id]; ok {
465				if old, ok := byTS[p.ts]; ok {
466					if old != p.value {
467						return nil, conflictAt(pos, ref, p.ts, old, p.value)
468					}
469					// 同批内重复出现且数值相同：重复，成功忽略。
470					continue
471				}
472			}
473			if sr, ok := s.series[id]; ok {
474				if old, ok := sr.points[p.ts]; ok {
475					if old != p.value {
476						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
477					}
478					// 与此前批次已写入的值相同：重复，成功忽略。
479					if seen[id] == nil {
480						seen[id] = map[int64]float64{}
481					}
482					seen[id][p.ts] = p.value
483					continue
484				}
485			}
486	
487			added++
488			if seen[id] == nil {
489				seen[id] = map[int64]float64{}
490			}
491			seen[id][p.ts] = p.value
492			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
493		}
494	
495		// 全部采样点合法且无冲突，原子提交本批新增点。
496		for _, c := range commits {
497			sr := s.series[c.id]
498			if sr == nil {
499				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
500				s.series[c.id] = sr
501			}
502			sr.points[c.ts] = c.val
503		}
504	
505		return s.snapshot(added, len(items)-added), nil
506	}
507	
508	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
509	func formatFloat(v float64) string {
510		return strconv.FormatFloat(v, 'g', -1, 64)
511	}
512	
513	type parsedQuery struct {
514		name   string
515		start  int64
516		end    int64
517		labels map[string]string
518	}
519	
520	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
521	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
522		q, err := parseQuery(raw)
523		if err != nil {
524			return nil, &LineError{Status: "error", Error: err.Error()}
525		}
526		if q.start > q.end {
527			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
528				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
529		}
530		return s.runQuery(q), nil
531	}
532	
533	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
534	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
535	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
536		var q parsedQuery
537		dec := json.NewDecoder(bytes.NewReader(raw))
538		dec.UseNumber()
539	
540		tok, err := dec.Token()
541		if err != nil {
542			return q, err
543		}
544		if d, ok := tok.(json.Delim); !ok || d != '{' {
545			return q, fmt.Errorf("each query must be a JSON object")
546		}
547	
548		present := make(map[string]bool)
549		for dec.More() {
550			keyTok, err := dec.Token()
551			if err != nil {
552				return q, err
553			}
554			key := keyTok.(string)
555			switch key {
556			case "op", "name", "start", "end", "labels":
557			default:
558				return q, fmt.Errorf("unknown field %q", key)
559			}
560			if present[key] {
561				return q, fmt.Errorf("duplicate field %q", key)
562			}
563			present[key] = true
564	
565			switch key {
566			case "op":
567				t, err := dec.Token()
568				if err != nil {
569					return q, err
570				}
571				op, ok := t.(string)
572				if !ok {
573					return q, fmt.Errorf(`field "op" must be a string`)
574				}
575				if op != "query" {
576					return q, fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
577				}
578			case "name":
579				t, err := dec.Token()
580				if err != nil {
581					return q, err
582				}
583				name, ok := t.(string)
584				if !ok {
585					return q, fmt.Errorf(`field "name" must be a string`)
586				}
587				if name == "" {
588					return q, fmt.Errorf(`field "name" must be a non-empty string`)
589				}
590				q.name = name
591			case "start", "end":
592				n, err := nextJSONNumber(dec, key)
593				if err != nil {
594					return q, err
595				}
596				v, err := parseJSONInt(n)
597				if err != nil {
598					return q, fmt.Errorf(`field %q: %s`, key, err)
599				}
600				if key == "start" {
601					q.start = v
602				} else {
603					q.end = v
604				}
605			case "labels":
606				labels, err := parseLabels(dec, `field "labels" must be an object of non-empty string keys to string values`)
607				if err != nil {
608					return q, err
609				}
610				q.labels = labels
611			}
612		}
613		if _, err := dec.Token(); err != nil { // 消耗 '}'
614			return q, err
615		}
616		if _, err := dec.Token(); err != io.EOF {
617			if err == nil {
618				return q, fmt.Errorf("unexpected content after the query object")
619			}
620			return q, err
621		}
622	
623		for _, field := range []string{"op", "name", "start", "end"} {
624			if !present[field] {
625				return q, fmt.Errorf("missing required field %q", field)
626			}
627		}
628		return q, nil
629	}
630	
631	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
632	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
633	func labelsMatch(want, stored map[string]string) bool {
634		for k, v := range want {
635			got, ok := stored[k]
636			if !ok || got != v {
637				return false
638			}
639		}
640		return true
641	}
642	
643	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
644	// 结果沿用 snapshot 的序列排序；无区间内点的序列不列出。
645	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
646		matched := make([]*storedSeries, 0)
647		for _, sr := range s.series {
648			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
649				continue
650			}
651			has := false
652			for ts := range sr.points {
653				if ts >= q.start && ts <= q.end {
654					has = true
655					break
656				}
657			}
658			if has {
659				matched = append(matched, sr)
660			}
661		}
662		sort.Slice(matched, func(i, j int) bool {
663			if matched[i].ref.Name != matched[j].ref.Name {
664				return matched[i].ref.Name < matched[j].ref.Name
665			}
666			return compareLabelPairs(sortedPairs(matched[i].ref.Labels), sortedPairs(matched[j].ref.Labels)) < 0
667		})
668	
669		out := make([]QuerySeries, 0, len(matched))
670		for _, sr := range matched {
671			tsList := make([]int64, 0, len(sr.points))
672			for ts := range sr.points {
673				if ts >= q.start && ts <= q.end {
674					tsList = append(tsList, ts)
675				}
676			}
677			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
678			values := make([]float64, len(tsList))
679			for i, ts := range tsList {
680				values[i] = sr.points[ts]
681			}
682			labels := cloneLabels(sr.ref.Labels)
683			out = append(out, QuerySeries{
684				Name:    sr.ref.Name,
685				Labels:  labels,
686				Count:   len(values),
687				Average: finiteMean(values),
688			})
689		}
690		return &QueryResult{Status: "ok", Op: "query", Series: out}
691	}
692	
693	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
694	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
695	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
696	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
697	// 只有一个点时结果就是该点的值。
698	func finiteMean(values []float64) float64 {
699		sum := new(big.Rat)
700		r := new(big.Rat)
701		for _, v := range values {
702			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
703			sum.Add(sum, r.SetFloat64(v))
704		}
705		sum.Quo(sum, r.SetInt64(int64(len(values))))
706		return ratToFloat64NearestEven(sum)
707	}
708	
709	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
710	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
711	func ratToFloat64NearestEven(x *big.Rat) float64 {
712		if x.Sign() == 0 {
713			return 0
714		}
715		num := new(big.Int).Set(x.Num())
716		den := x.Denom()
717		neg := num.Sign() < 0
718		if neg {
719			num.Neg(num)
720		}
721	
722		// e 满足 2^e <= num/den < 2^(e+1)。
723		e := floorLog2Rat(num, den)
724		var m *big.Int
725		scale := 0
726		if e >= -1022 {
727			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
728			scale = e - 52
729			m = roundScaledRatio(num, den, scale)
730			if m.BitLen() == 54 {
731				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
732				m.Rsh(m, 1)
733				scale++
734			}
735		} else {
736			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
737			scale = -1074
738			m = roundScaledRatio(num, den, scale)
739		}
740		// m < 2^53，可以精确放入 int64 与 float64。
741		f := math.Ldexp(float64(m.Int64()), scale)
742		if neg {
743			return -f
744		}
745		return f
746	}
747	
748	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
749	func floorLog2Rat(num, den *big.Int) int {
750		k := num.BitLen() - den.BitLen()
751		var t big.Int
752		if k >= 0 {
753			t.Lsh(den, uint(k))
754			if num.Cmp(&t) >= 0 {
755				return k
756			}
757			return k - 1
758		}
759		t.Lsh(num, uint(-k))
760		if t.Cmp(den) >= 0 {
761			return k
762		}
763		return k - 1
764	}
765	
766	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
767	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
768		n := new(big.Int).Set(num)
769		d := new(big.Int).Set(den)
770		if scale >= 0 {
771			d.Lsh(d, uint(scale))
772		} else {
773			n.Lsh(n, uint(-scale))
774		}
775		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
776		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
777		case 1:
778			q.Add(q, big.NewInt(1))
779		case 0:
780			if q.Bit(0) == 1 {
781				q.Add(q, big.NewInt(1))
782			}
783		}
784		return q
785	}
786	
787	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
788	func (r SeriesRef) String() string {
789		var b strings.Builder
790		b.WriteString(r.Name)
791		b.WriteByte('{')
792		for i, p := range sortedPairs(r.Labels) {
793			if i > 0 {
794				b.WriteByte(',')
795			}
796			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
797		}
798		b.WriteByte('}')
799		return b.String()
800	}
801	
802	// snapshot 生成按规范排序的全部序列视图：先按指标名，再按标签键值对字典序，
803	// 序列内按时间戳升序。
804	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
805		views := make([]SeriesView, 0, len(s.series))
806		for _, sr := range s.series {
807			tsList := make([]int64, 0, len(sr.points))
808			for ts := range sr.points {
809				tsList = append(tsList, ts)
810			}
811			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
812			points := make([]Point, len(tsList))
813			for i, ts := range tsList {
814				points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
815			}
816			views = append(views, SeriesView{Name: sr.ref.Name, Labels: cloneLabels(sr.ref.Labels), Points: points})
817		}
818		sort.Slice(views, func(i, j int) bool {
819			if views[i].Name != views[j].Name {
820				return views[i].Name < views[j].Name
821			}
822			return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
823		})
824		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
825	}
826

